function renderGuideGrid(rows){const q=($('#guideSearch')?.value||'').trim().toLowerCase();const list=(rows||[]).filter(g=>!q||`${g.title} ${g.destination}`.toLowerCase().includes(q)).slice(0,12);$('#guideGrid').innerHTML=list.length?list.map(g=>`<article class="guideTile" data-guide-id="${g.id}" tabindex="0"><div class="guideTileImage"><img src="${esc(g.hero_image)}" alt="${esc(g.destination)}"></div><div class="guideTileBody"><span>${esc(g.destination)}</span><h3>${esc(g.title)}</h3><p>${esc(g.intro).slice(0,115)}${g.intro.length>115?'…':''}</p><small>${guideDateBR(g.published_at)}</small></div></article>`).join(''):'<div class="empty">Nenhum guia encontrado.</div>';$$('.guideTile').forEach(x=>{const open=()=>openGuide(Number(x.dataset.guideId));x.onclick=open;x.onkeydown=e=>{if(e.key==='Enter')open()}})}
async function openGuide(id){try{const g=await api('/api/guides/'+id);show('guideDetail');window.scrollTo(0,0);$('#guideDetailContent').innerHTML=`<section class="guideHero"><img src="${esc(g.hero_image)}" alt="${esc(g.destination)}"><div class="guideHeroShade"></div><div class="guideHeroText"><span>${esc(g.destination)}</span><h1>${esc(g.title)}</h1></div></section><div class="guideArticle"><div class="guideMeta">Publicado em ${guideDateBR(g.published_at)}</div><p class="guideIntro">${esc(g.intro).replace(/\n/g,'<br>')}</p><div class="guideSections">${(g.sections||[]).map((s,i)=>`<details class="guideSection" ${i===0?'open':''}><summary><div><h2>${esc(s.title)}</h2><small>${(s.cards||[]).length} ${((s.cards||[]).length===1?'lugar':'lugares')}</small></div><span>⌄</span></summary><div class="guideCards">${(s.cards||[]).map((c,n)=>`<article class="guidePlaceCard"><div class="guidePlaceCopy"><div class="guidePlaceTitle"><span>${n+1}</span><h3>${esc(c.name)}</h3></div>${c.price?`<div class="guidePrice">${esc(c.price)}</div>`:''}<p>${esc(c.description)}</p></div><div class="guidePlacePhoto">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:''}</div></article>`).join('')}</div></details>`).join('')}</div></div>`}catch(e){alert(e.message)}}
