function renderGuideBuilder(){const host=$('#guideSectionsBuilder');host.innerHTML=guideDraftSections.length?guideDraftSections.map((sec,si)=>`<section class="guideSectionEditor"><div class="guideSectionEditorHead"><label>Nome da seção<input class="guideSectionTitle" data-si="${si}" value="${esc(sec.title)}" placeholder="Ex.: Portugal • Restaurantes"></label><button type="button" class="removeGuideSection" data-si="${si}">Remover seção</button></div><div class="guideDraftCards">${(sec.cards||[]).map((c,ci)=>`<article class="guideDraftCard"><div>${c.image?`<img src="${esc(c.image)}" alt="">`:''}</div><div><strong>${esc(c.name)}</strong><span>${esc(c.price)}</span><p>${esc(c.description)}</p></div><button type="button" class="removeGuideCard" data-si="${si}" data-ci="${ci}">Remover</button></article>`).join('')}</div><div class="guideCardEditor"><h4>Adicionar card</h4><label>Nome do lugar<input class="newCardName" data-si="${si}" maxlength="140" placeholder="Nome do lugar"></label><label>Imagem do local<input class="newCardImage" data-si="${si}" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Descrição<textarea class="newCardDescription" data-si="${si}" rows="3" maxlength="2000"></textarea></label><label>Preço<select class="newCardPrice" data-si="${si}"><option value="$">$</option><option value="$$" selected>$$</option><option value="$$$">$$$</option><option value="$$$$">$$$$</option></select></label><button type="button" class="primary addGuideCard" data-si="${si}">Adicionar card à seção</button></div></section>`).join(''):'<div class="empty">Adicione a primeira seção do guia.</div>';
  $$('.guideSectionTitle').forEach(x=>x.oninput=()=>guideDraftSections[+x.dataset.si].title=x.value);$$('.removeGuideSection').forEach(x=>x.onclick=()=>{guideDraftSections.splice(+x.dataset.si,1);renderGuideBuilder()});$$('.removeGuideCard').forEach(x=>x.onclick=()=>{guideDraftSections[+x.dataset.si].cards.splice(+x.dataset.ci,1);renderGuideBuilder()});$$('.addGuideCard').forEach(x=>x.onclick=async()=>{const si=+x.dataset.si,name=$(`.newCardName[data-si="${si}"]`).value.trim(),desc=$(`.newCardDescription[data-si="${si}"]`).value.trim(),price=$(`.newCardPrice[data-si="${si}"]`).value,file=$(`.newCardImage[data-si="${si}"]`).files[0];if(!name||!desc||!file){$('#guideMsg').textContent='Preencha Nome do lugar, Imagem do local e Descrição antes de adicionar o card.';return}try{x.disabled=true;const image=await imageFileToDataUrl(file);guideDraftSections[si].cards.push({name,image,description:desc,price});$('#guideMsg').textContent='';renderGuideBuilder()}catch(e){$('#guideMsg').textContent=e.message}finally{x.disabled=false}})}
