function closeGuideDialog(){if($('#guideDialog').open)$('#guideDialog').close()}
$('#guideCancel').onclick=closeGuideDialog;$('#guideClose').onclick=closeGuideDialog;$('#guideDialog').addEventListener('click',e=>{if(e.target===$('#guideDialog'))closeGuideDialog()});
$('#guideForm').onsubmit=async e=>{e.preventDefault();try{const destination=$('#guideDestination').value.trim(),title=$('#guideTitle').value.trim(),hero=$('#guideHero').value,intro=$('#guideIntro').value.trim();if(!destination||!title||!hero||!intro)throw new Error('Preencha Destino, Título, Imagem de capa e Texto de apresentação.');if(!guideDraftSections.length)throw new Error('Adicione pelo menos uma seção.');for(const s of guideDraftSections){if(!s.title.trim())throw new Error('Informe o nome de todas as seções.');if(!s.cards.length)throw new Error(`Adicione pelo menos um card na seção “${s.title}”.`)}const payload={title,destination,hero_image:hero,intro,published_at:$('#guideDate').value||localISODate(),sections:guideDraftSections};const id=$('#guideId').value;const saved=await api(id?'/api/admin/guides/'+id:'/api/admin/guides',{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeGuideDialog();await loadAdminGuides();travelGuides=await api('/api/guides');renderGuideGrid(travelGuides);alert(id?'Guia atualizado com sucesso.':'Guia publicado com sucesso.')}catch(err){$('#guideMsg').textContent=err.message}};

